// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { GlobeIcon, LaptopIcon, ServerIcon } from 'lucide-react'

import { DemoStage, Label, PanelChrome, Toggle, type Build } from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { CAPTIONS, LOG, RULES } from './script'

const TONE = { muted: 'text-muted', cyan: 'text-[#22d3ee]', emerald: 'text-emerald' } as const

const build: Build = ({ tl, q, qa, pos, step, final, move, click, wait, scramble, cursorOut }) => {
  const send = (packet: string, from: string, to: string, at?: string, duration = 0.55) => {
    const node = q(packet)
    const half = { x: node.offsetWidth / 2, y: node.offsetHeight / 2 }
    const a = pos(from)
    const b = pos(to)
    tl.fromTo(
      node,
      { x: a.x - half.x, y: a.y - half.y, opacity: 1 },
      { x: b.x - half.x, y: b.y - half.y, duration, ease: 'power2.inOut', immediateRender: false },
      at,
    )
  }
  const hide = (packet: string) => tl.to(q(packet), { opacity: 0, duration: 0.15 })
  const pulse = (node: string) =>
    tl.fromTo(
      q(`${node}-ring`),
      { scale: 0.9, opacity: 0.9 },
      { scale: 1.25, opacity: 0, duration: 0.5, ease: 'power2.out' },
      '>',
    )
  const log = (index: number) =>
    tl.fromTo(
      qa('log-row')[index],
      { opacity: 0, x: -12 },
      { opacity: 1, x: 0, duration: 0.3, ease: 'power3.out' },
      '<0.05',
    )
  const toggle = (name: string, on: boolean) => {
    tl.to(q(`${name}-knob`), { x: on ? 12 : 0, duration: 0.2, ease: 'power2.out' }, '<')
    tl.to(q(`${name}-fill`), { opacity: on ? 1 : 0, duration: 0.2 }, '<')
  }

  step(0)
  send('pkt-a', 'page', 'core')
  pulse('core')
  send('pkt-a', 'core', 'api', '<')
  pulse('api')
  log(0)
  hide('pkt-a')
  send('pkt-b', 'page', 'core', '-=0.4')
  pulse('core')
  send('pkt-b', 'core', 'api', '<')
  pulse('api')
  log(1)
  hide('pkt-b')

  step(1, '+=0.3')
  move('rule-0-toggle')
  click('rule-0-toggle')
  toggle('rule-0-toggle', true)
  tl.to(q('rule-0'), { borderColor: 'rgba(34,211,238,0.55)', duration: 0.2 }, '<')
  send('pkt-c', 'page', 'core', '+=0.1')
  pulse('core')
  scramble('pkt-c-text', 'localhost/user', { at: '<', duration: 0.5 })
  tl.to(q('pkt-c'), { borderColor: 'rgba(34,211,238,0.8)', color: '#22d3ee', duration: 0.2 }, '<')
  send('pkt-c', 'core', 'local', '>')
  pulse('local')
  log(2)
  hide('pkt-c')

  step(2, '+=0.3')
  move('rule-1-toggle')
  click('rule-1-toggle')
  toggle('rule-1-toggle', true)
  tl.to(q('rule-1'), { borderColor: 'rgba(52,211,153,0.55)', duration: 0.2 }, '<')
  send('pkt-d', 'page', 'core', '+=0.1')
  pulse('core')
  tl.to(q('pkt-d'), { opacity: 0, duration: 0.15 }, '<')
  send('pkt-mock', 'core', 'page', '<', 0.5)
  pulse('page')
  log(3)
  hide('pkt-mock')

  step(3, '+=0.3')
  move('pause', { ax: 0.3 })
  click('pause')
  toggle('pause', true)
  tl.to(q('rules'), { boxShadow: 'inset 0 0 0 1px rgba(251,191,36,0.45)', duration: 0.25 }, '<')
  tl.to(q('paused'), { opacity: 1, duration: 0.2 }, '<')
  send('pkt-e', 'page', 'core', '+=0.1')
  send('pkt-e', 'core', 'api', '>', 0.45)
  pulse('api')
  log(4)
  hide('pkt-e')
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

function Node({
  d,
  icon: Icon,
  label,
  className,
}: {
  d: string
  icon: typeof GlobeIcon
  label: string
  className: string
}) {
  return (
    <div
      data-d={d}
      className={cn(
        'absolute flex h-9 w-[126px] items-center gap-1.5 rounded-lg border border-line-strong bg-surface px-2 text-[9.5px] text-ink-soft',
        className,
      )}
    >
      <span
        data-d={`${d}-ring`}
        className="absolute inset-0 rounded-lg border-2 border-[var(--accent)] opacity-0"
      />
      <Icon className="size-3.5 shrink-0 text-[var(--accent)]" />
      <span className="truncate font-mono">{label}</span>
    </div>
  )
}

function Packet({ d, children, className }: { d: string; children: string; className?: string }) {
  return (
    <span
      data-d={d}
      className={cn(
        'absolute left-0 top-0 z-30 w-[104px] truncate rounded-full border border-ink/25 bg-elevated px-2 py-0.5 text-center font-mono text-[9px] text-ink opacity-0 shadow-lg',
        className,
      )}
    >
      <span data-d={`${d}-text`}>{children}</span>
    </span>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="HTTP Interceptor redirecting a request to localhost, mocking another, and pausing all rules"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span data-d="pause" className="flex items-center gap-1.5 text-[10px] text-muted">
            Pause all <Toggle d="pause" />
          </span>
        }
      >
        <div className="flex h-full flex-col gap-2.5">
          <div className="relative h-[124px] shrink-0 rounded-xl border border-line bg-canvas/60">
            <svg className="absolute inset-0 size-full text-white/15" aria-hidden>
              <line x1="58" y1="62" x2="50%" y2="62" stroke="currentColor" strokeDasharray="3 4" />
              <line x1="50%" y1="62" x2="90%" y2="26" stroke="currentColor" strokeDasharray="3 4" />
              <line x1="50%" y1="62" x2="90%" y2="98" stroke="currentColor" strokeDasharray="3 4" />
            </svg>
            <Node d="page" icon={GlobeIcon} label="app.acme.com" className="left-2 top-[44px]" />
            <div
              data-d="core"
              className="absolute left-[calc(50%-22px)] top-[40px] flex size-11 items-center justify-center rounded-full border border-[var(--accent)]/60 bg-[#0d1a1f]"
            >
              <span
                data-d="core-ring"
                className="absolute inset-0 rounded-full border-2 border-[var(--accent)] opacity-0"
              />
              <span className="text-[8.5px] font-medium text-[var(--accent)]">rules</span>
            </div>
            <Node d="api" icon={ServerIcon} label="api.acme.com" className="right-2 top-[8px]" />
            <Node
              d="local"
              icon={LaptopIcon}
              label="localhost:3000"
              className="right-2 top-[80px]"
            />
            <span
              data-d="paused"
              className="absolute left-1/2 top-[94px] -translate-x-1/2 rounded-full bg-amber/15 px-2 py-0.5 text-[9px] text-amber opacity-0"
            >
              Rules paused
            </span>
          </div>

          <div className="grid min-h-0 flex-1 grid-cols-[1fr_1.1fr] gap-2.5">
            <div data-d="rules" className="space-y-1.5">
              <Label>Rules</Label>
              {RULES.map((rule, index) => (
                <div
                  key={rule.kind}
                  data-d={`rule-${index}`}
                  className="flex items-center gap-2 rounded-lg border border-line bg-canvas/60 px-2 py-1.5 shadow-none"
                >
                  <div className="min-w-0 flex-1">
                    <p className="text-[10px] font-medium text-ink">{rule.kind}</p>
                    <p className="truncate font-mono text-[8.5px] text-muted">{rule.detail}</p>
                  </div>
                  <Toggle d={`rule-${index}-toggle`} />
                </div>
              ))}
            </div>
            <div className="min-w-0 space-y-1">
              <Label>Network log</Label>
              <div className="space-y-1 rounded-lg border border-line bg-canvas/60 p-2 font-mono text-[9px]">
                {LOG.map((row, index) => (
                  <p key={index} data-d="log-row" className="flex gap-1.5 truncate opacity-0">
                    <span className="text-[#22d3ee]">{row.method}</span>
                    <span className="text-ink-soft">{row.path}</span>
                    <span className={cn('ml-auto shrink-0', TONE[row.tone])}>{row.note}</span>
                  </p>
                ))}
              </div>
            </div>
          </div>
        </div>
      </PanelChrome>
      <Packet d="pkt-a">GET /api/user</Packet>
      <Packet d="pkt-b">GET /api/flags</Packet>
      <Packet d="pkt-c">api.acme.com/user</Packet>
      <Packet d="pkt-d">GET /api/flags</Packet>
      <Packet d="pkt-mock" className="border-emerald/70 text-emerald">
        200 mock
      </Packet>
      <Packet d="pkt-e">GET /api/user</Packet>
    </DemoStage>
  )
}
